WITH oracle_1 AS (WITH benchmark AS (SELECT b.volume FROM `newzl`.`hsj_stock_hq_basic` AS b INNER JOIN `newzl`.`hsj_stock_code_info` AS s ON s.mktcode=b.mktcode AND s.tgtcode=b.tgtcode WHERE s.name='贵州茅台' AND b.bizdate='2026-04-14') SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` AS b CROSS JOIN benchmark AS q WHERE b.mktcode=1 AND b.bizdate='2026-04-14' AND b.volume>q.volume), branch_1 AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM oracle_1 o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode IN (0,1) AND q.volume>=1), oracle_2 AS (SELECT mktcode,tgtcode,bizdate FROM `newzl`.`hsj_stock_hq_basic_technical` WHERE bizdate='2026-04-14' AND ABS(ma5-ma20)/NULLIF(GREATEST(ABS(ma5),ABS(ma20)),0)<=0.03), branch_2 AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM oracle_2 o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode=1 AND q.volume>=10) SELECT mktcode,tgtcode,bizdate FROM branch_1 UNION DISTINCT SELECT mktcode,tgtcode,bizdate FROM branch_2;
